<script setup lang="ts">
definePageMeta({ layout: 'dashboard' })
type User = { id: string; name: string; email: string; role: 'user' | 'admin'; created_at: string }
type Course = { id: string; title: string; description: string; learning_objectives: string; image: string; level: string; category: string; duration: string; uploaded_at: string }
const { user, loadUser } = useAuth()
const users = ref<User[]>([])
const courses = ref<Course[]>([])
const loading = ref(true)
const errorMessage = ref('')
const editing = ref<Course | null>(null)
const form = reactive({ title: '', description: '', learningObjectives: '', image: '', level: 'beginner', category: '', duration: '', uploadedAt: new Date().toISOString().slice(0, 10) })
async function loadAdminData() { if (!await loadUser()) return navigateTo({ path: '/login', query: { redirect: '/admin' } }); if (user.value?.role !== 'admin') return navigateTo('/dashboard'); const [userResult, courseResult] = await Promise.all([$fetch<{ users: User[] }>('/api/admin/users'), $fetch<{ courses: Course[] }>('/api/admin/courses')]); users.value = userResult.users; courses.value = courseResult.courses; loading.value = false }
async function updateUser(item: User) { await $fetch(`/api/admin/users/${item.id}`, { method: 'PATCH', body: { name: item.name, role: item.role } }) }
async function deleteUser(id: string) { await $fetch(`/api/admin/users/${id}`, { method: 'DELETE' }); await loadAdminData() }
function editCourse(item: Course) { editing.value = item; Object.assign(form, { title: item.title, description: item.description, learningObjectives: item.learning_objectives, image: item.image, level: item.level, category: item.category, duration: item.duration, uploadedAt: item.uploaded_at }) }
function resetForm() { editing.value = null; Object.assign(form, { title: '', description: '', learningObjectives: '', image: '', level: 'beginner', category: '', duration: '', uploadedAt: new Date().toISOString().slice(0, 10) }) }
async function saveCourse() { errorMessage.value = ''; try { if (editing.value) await $fetch(`/api/admin/courses/${editing.value.id}`, { method: 'PUT', body: form }); else await $fetch('/api/admin/courses', { method: 'POST', body: form }); resetForm(); await loadAdminData() } catch (error: any) { errorMessage.value = error.data?.statusMessage || error.data?.message || 'Course gagal disimpan' } }
async function deleteCourse(id: string) { await $fetch(`/api/admin/courses/${id}`, { method: 'DELETE' }); await loadAdminData() }
onMounted(loadAdminData)
</script>
<template>
  <UDashboardPanel id="admin"><template #header><UDashboardNavbar title="Admin Panel"><template #leading><UDashboardSidebarCollapse /></template><template #right><UButton label="Course Baru" icon="i-lucide-plus" color="primary" @click="resetForm" /></template></UDashboardNavbar><UDashboardToolbar><template #left><span class="text-sm text-muted">Manage users dan courses</span></template></UDashboardToolbar></template><template #body><div v-if="loading" class="p-8 text-muted">Memuat admin panel...</div><div v-else class="space-y-6"><p v-if="errorMessage" class="text-error">{{ errorMessage }}</p><UPageGrid id="users" class="lg:grid-cols-3"><UPageCard title="Total users" :description="`${users.length} akun terdaftar`" icon="i-lucide-users" variant="subtle"><strong class="text-3xl text-highlighted">{{ users.length }}</strong></UPageCard><UPageCard title="Total courses" :description="`${courses.length} course tersedia`" icon="i-lucide-book-open" variant="subtle"><strong class="text-3xl text-highlighted">{{ courses.length }}</strong></UPageCard><UPageCard title="Role aktif" description="Session administrator" icon="i-lucide-shield-check" variant="subtle"><strong class="text-3xl text-highlighted">Admin</strong></UPageCard></UPageGrid><UPageCard title="Manage User" description="Kelola akun dan role pengguna." icon="i-lucide-users"><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b border-default text-left"><th class="p-3">Nama</th><th class="p-3">Email</th><th class="p-3">Role</th><th class="p-3">Aksi</th></tr></thead><tbody><tr v-for="item in users" :key="item.id" class="border-b border-default"><td class="p-3"><UInput v-model="item.name" @change="updateUser(item)" /></td><td class="p-3">{{ item.email }}</td><td class="p-3"><USelect v-model="item.role" :items="['user', 'admin']" :disabled="item.id === user?.id" @change="updateUser(item)" /></td><td class="p-3"><UButton label="Hapus" color="error" variant="ghost" :disabled="item.id === user?.id" @click="deleteUser(item.id)" /></td></tr></tbody></table></div></UPageCard><UPageCard id="courses" title="Manage Course" description="Buat, edit, dan hapus course." icon="i-lucide-book-open"><form class="grid gap-3 md:grid-cols-3" @submit.prevent="saveCourse"><UInput v-model="form.title" placeholder="Judul course" required /><UInput v-model="form.category" placeholder="Kategori" required /><UInput v-model="form.duration" placeholder="Durasi" required /><UInput v-model="form.image" placeholder="URL gambar" required /><USelect v-model="form.level" :items="[{ label: 'Dasar', value: 'beginner' }, { label: 'Menengah', value: 'intermediate' }, { label: 'Sulit', value: 'advanced' }]" value-key="value" /><UInput v-model="form.uploadedAt" type="date" required /><UTextarea v-model="form.description" class="md:col-span-3" placeholder="Deskripsi" required /><UTextarea v-model="form.learningObjectives" class="md:col-span-3" placeholder="Tujuan pembelajaran" required /><div class="flex gap-2 md:col-span-3"><UButton type="submit" :label="editing ? 'Simpan Perubahan' : 'Tambah Course'" color="primary" /><UButton v-if="editing" label="Batal" color="neutral" variant="outline" type="button" @click="resetForm" /></div></form><div class="mt-6 grid gap-3"><div v-for="item in courses" :key="item.id" class="flex items-center justify-between gap-4 rounded-lg border border-default p-4"><div><strong class="text-highlighted">{{ item.title }}</strong><p class="text-sm text-muted">{{ item.category }} · {{ item.level }}</p></div><div class="flex gap-2"><UButton label="Edit" color="primary" variant="ghost" @click="editCourse(item)" /><UButton label="Hapus" color="error" variant="ghost" @click="deleteCourse(item.id)" /></div></div></div></UPageCard></div></template></UDashboardPanel>
</template>
